public static implicit operator Matrix3x2F(System.Drawing.Drawing2D.Matrix matrix)
        {
            Matrix3x2F r = new Matrix3x2F();
            float[] elms = matrix.Elements;
            r.M11 = elms[0];
            r.M12 = elms[1];
            r.M21 = elms[2];
            r.M22 = elms[3];
            r.DX = elms[4];
            r.DY = elms[5];
            return r;
        }

