                LinearGradientBrush br = new LinearGradientBrush(new Rectangle(2,2, Width - 4, 1), AdobeColors.HSL_to_RGB(hsl_start), AdobeColors.HSL_to_RGB(hsl_end), 0, false); 
                g.FillRectangle(br,new Rectangle(2,i + 2, Width - 4, 1)); 
            }

