                {
                    if (col == 0 && CheckBoxes)
                    {
                        if (e.X < CheckBoxWidth)
                            return;
                    }

                    if (m_currentRow != row || m_currentCol != col)
                    {
                        DisableEditingControl(true);
                    }
                    m_currentRow = row;
                    m_currentCol = col;
                    OnCellClicked(item);
                }
            }

