                            {
                                m_hmapRowsCmbox.SelectedItem = r;
                                break;
                            }
                        }                        
                    }
                    else
                    {
                        m_importedHeightMap.Dispose();
                        m_importedHeightMap = null;
                        error = "unsupported file type ";
                    }
                        
                    if (!string.IsNullOrEmpty(error))
